CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE households(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL,monthly_limit INTEGER NOT NULL DEFAULT 15000000,created_at TEXT NOT NULL);
CREATE TABLE household_members(household_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',joined_at TEXT NOT NULL,PRIMARY KEY(household_id,user_id));
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE categories(id TEXT PRIMARY KEY,household_id TEXT NOT NULL,name TEXT NOT NULL,pct REAL NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE goals(id TEXT PRIMARY KEY,household_id TEXT NOT NULL,name TEXT NOT NULL,target INTEGER NOT NULL DEFAULT 0,current INTEGER NOT NULL DEFAULT 0,target_date TEXT,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE transactions(id TEXT PRIMARY KEY,household_id TEXT NOT NULL,user_id TEXT NOT NULL,type TEXT NOT NULL,amount INTEGER NOT NULL,note TEXT NOT NULL,category_id TEXT,goal_id TEXT,tx_date TEXT NOT NULL,need INTEGER NOT NULL DEFAULT 1,source TEXT NOT NULL DEFAULT 'manual',paid_by TEXT NOT NULL DEFAULT 'shared',receipt_url TEXT,external_ref TEXT,created_at TEXT NOT NULL);
CREATE TABLE invites(token TEXT PRIMARY KEY,household_id TEXT NOT NULL,created_by TEXT NOT NULL,expires_at TEXT NOT NULL,used_by TEXT);
CREATE TABLE oauth_states(state TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE gmail_tokens(user_id TEXT PRIMARY KEY,token_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE receipts(id TEXT PRIMARY KEY,household_id TEXT NOT NULL,data_url TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE household_defaults(household_id TEXT PRIMARY KEY,initialized_at TEXT NOT NULL);
CREATE INDEX idx_members_user ON household_members(user_id);
CREATE INDEX idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX idx_categories_household ON categories(household_id);
CREATE INDEX idx_goals_household ON goals(household_id);
CREATE INDEX idx_transactions_household_date ON transactions(household_id,tx_date DESC,created_at DESC);
CREATE INDEX idx_transactions_household_goal ON transactions(household_id,goal_id,type);
CREATE UNIQUE INDEX idx_transactions_external_ref ON transactions(household_id,external_ref) WHERE external_ref IS NOT NULL;
